```
#!/usr/bin/perl

use List::Util qw(max min);

# Get user input
print "Enter a list of numbers separated by spaces:\n";
my $input = <STDIN>;

# Create array from input
my @numbers = split(' ', $input);

# Check if any elements are missing
if (@numbers == 0) {
    die "Error: Input must contain at least one number.\n";
}

# Initialize variables
my $sum = 0;
my $count = 0;
my $max = $numbers[0];
my $min = $numbers[0];

# Loop through array, update variables
foreach my $num (@numbers) {
    # Check if element is a number
    unless ($num =~ /^-?\d*\.?\d+$/) {
        die "Error: Invalid input. Input must be a list of numbers separated by spaces.\n";
    }
    $sum += $num;
    $count++;
    $max = max($max, $num);
    $min = min($min, $num);
}

# Calculate the average
my $average = $sum / $count;

# Sort the array in ascending order
my @sorted_numbers = sort {$a <=> $b} @numbers;

# Print the results
print "The sum of the numbers is: $sum\n";
print "The average of the numbers is: $average\n";
print "The maximum value is: $max\n";
print "The minimum value is: $min\n";
print "The sorted array is: @sorted_numbers\n";

# Exit script
exit;
```

