# Define error handling function
function Handle-Error {
    param([string]$msg)
    Write-Host "Error: $msg" -ForegroundColor Red
}

# Retrieve process information using WMI
$processes = Get-WmiObject Win32_Process -ErrorAction SilentlyContinue
if (!$processes) {
    Handle-Error "Failed to retrieve process information using WMI."
    return
}

# Format process information and display it
$results = @()
$totalCpuUsage = 0
foreach ($process in $processes) {
    try {
        $owner = $process.GetOwner()
    } catch {
        $owner = "Access Denied"
    }
    $cpuUsage = [Math]::Round($process.PercentProcessorTime, 2)
    $totalCpuUsage += $cpuUsage
    $startTime = [System.Management.ManagementDateTimeConverter]::ToDateTime($process.CreationDate)
    $result = [PSCustomObject]@{
        "Name" = $process.Name
        "ID" = $process.ProcessId
        "Memory Usage (MB)" = [Math]::Round($process.WorkingSetSize / 1MB, 2)
        "CPU Usage (%)" = $cpuUsage
        "Start Time" = $startTime
        "User" = "$($owner.Domain)\$($owner.User)"
    }
    $results += $result
}
$averageCpuUsage = [Math]::Round(($totalCpuUsage / $results.Count), 2)
$results | Format-Table -AutoSize

# Display average CPU usage
Write-Host "Average CPU Usage (%): $averageCpuUsage"

# Allow for filtering and sorting
$filter = Read-Host "Enter a filter (e.g. 'chrome', '> 100 MB', '< 10% CPU usage'):"
if ($filter) {
    $results = $results | where {Invoke-Expression "$_.$($filter.trim())"}
}
$sort = Read-Host "Enter a sort order (e.g. 'CPU Usage (ASC)', 'Memory Usage (DESC)', 'Start Time (ASC)'):"
if ($sort) {
    $sortOrder = $sort.split("(")[1].split(")")[0]
    $propertyName = $sort.split("(")[0].Trim()
    if ($propertyName -eq "Start Time") {
        $results = $results | Sort-Object -Property @{Expression={$_.StartTime};Ascending=($sortOrder -eq "ASC")}
    } else {
        $results = $results | Sort-Object -Property $propertyName -Descending:($sortOrder -eq "DESC")
    }
}
$results | Format-Table -AutoSize
