#include <stdio.h>

int gcd(int a, int b);

int main() {
    int x, y;

    printf("Enter two integers: ");
    scanf("%d %d", &x, &y);

    int result = gcd(x, y);

    printf("The greatest common divisor of %d and %d is %d\n", x, y, result);

    return 0;
}

int gcd(int a, int b) {
    if (a == 0) {
        return b;
    } else {
        return gcd(b % a, a);
    }
}
```

